'use strict';
/* REGUL ARENA — Banques (source unique serveur). MODIFIÉ : migré depuis index.html (anti-plagiat + fix QN serveur). */
const QR = [{"cat":"Définitions & terminologie","q":"Selon le Règlement RFE UEMOA, qu'est-ce qu'un « intermédiaire agréé » ?","choices":["Tout établissement de crédit installé dans l'UEMOA ayant reçu la qualité d'intermédiaire agréé par agrément du Ministre chargé des Finances","Tout commerçant autorisé à effectuer des opérations de change","Tout particulier ayant déclaré son activité à la BCEAO","Toute personne morale ayant un compte ouvert auprès de la BCEAO"],"answer":0,"source":"Règlement n°06/2024/CM/UEMOA — Art. 2 (Définitions, point 41)"},{"cat":"Définitions & terminologie","q":"Qui sont considérés comme « non-résidents » au sens du Règlement RFE UEMOA ?","choices":["Les personnes physiques ayant leur principal centre d'intérêt à l'étranger, les fonctionnaires étrangers en poste dans un État UEMOA, et les personnes morales pour leurs établissements à l'étranger","Uniquement les personnes physiques de nationalité étrangère","Les voyageurs séjournant moins de 90 jours dans un État UEMOA","Toutes les personnes morales étrangères"],"answer":0,"source":"Règlement n°06/2024/CM/UEMOA — Art. 2 (Définitions, point 51)"},{"cat":"Définitions & terminologie","q":"Au sens du Règlement RFE UEMOA, en dessous de quel seuil de participation au capital d'une société une opération n'est-elle PAS considérée comme un « investissement direct » ?","choices":["5%","10%","20%","25%"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 2 (Définitions, points 43 et 44)"},{"cat":"Définitions & terminologie","q":"Que désigne le « principal centre d'intérêt » d'une personne physique selon le Règlement RFE UEMOA ?","choices":["Son lieu de naissance","Le lieu où elle exerce sa principale activité économique — nul ne peut en posséder plus d'un","Le pays où elle a sa résidence fiscale","Le pays de sa nationalité"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 2 (Définitions, point 14 — centre d'intérêt économique prédominant)"},{"cat":"Définitions & terminologie","q":"Qui est qualifié d'« agréé de change manuel » dans la réglementation UEMOA ?","choices":["Toute banque agréée par la BCEAO","Toute personne morale installée dans l'UEMOA ayant reçu un agrément du Ministre chargé des Finances pour exécuter des opérations de change manuel","Tout bureau de poste habilité aux transferts","Toute SGI agréée par le CREPMF"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 2 (Définitions, point 1)"},{"cat":"Intermédiaires & cession","q":"Par l'entremise de qui peuvent être effectuées les opérations de change et règlements entre un État UEMOA et l'étranger ?","choices":["Uniquement la BCEAO","La BCEAO, l'Administration ou Office des Postes, un intermédiaire agréé ou un agréé de change manuel, dans leurs compétences respectives","Toute personne physique majeure","Uniquement les intermédiaires agréés et la BCEAO"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 4 (Intermédiaires chargés d'exécuter les opérations)"},{"cat":"Intermédiaires & cession","q":"Dans quel délai maximum les revenus ou produits en devises encaissés à l'étranger par un résident doivent-ils être cédés à une banque intermédiaire agréée ?","choices":["7 jours","15 jours","1 mois à compter de la date d'exigibilité du paiement","3 mois"],"answer":2,"source":"Règlement n°06/2024/CM/UEMOA — Art. 5 et Annexe IX-1 (rapatriement sous 1 mois à compter de l'exigibilité)"},{"cat":"Intermédiaires & cession","q":"En matière d'exportation, à quelle date la date d'exigibilité du paiement est-elle fixée par le Règlement RFE UEMOA ?","choices":["À la date d'expédition des marchandises","À la date prévue au contrat commercial, qui ne doit pas dépasser 120 jours après l'expédition des marchandises","À la date d'arrivée des marchandises à destination","À la date d'émission de la facture"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 5 et Annexe II + Instruction BCEAO RFE 2025 (délai d'exigibilité fixé par la BCEAO)"},{"cat":"Intermédiaires & cession","q":"Quelle est l'obligation des résidents concernant les devises encaissées à l'étranger ou versées par un non-résident ?","choices":["Les conserver dans un coffre-fort agréé","Les céder à une banque intermédiaire agréée","Les déclarer uniquement au fisc","Les rapatrier en espèces dans un délai d'un an"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 5 (Cession de devises)"},{"cat":"Opérations courantes","q":"Quel est le montant maximum d'un transfert vers l'étranger pour lequel AUCUNE pièce justificative n'est requise (au-delà de l'identification du demandeur et bénéficiaire) ?","choices":["100.000 FCFA","500.000 FCFA","1.000.000 FCFA","5.000.000 FCFA"],"answer":2,"source":"Règlement n°06/2024/CM/UEMOA — Art. 9 (dispense de pièces justificatives sous seuil fixé par la BCEAO)"},{"cat":"Opérations courantes","q":"Parmi les opérations suivantes, laquelle est autorisée à titre général pour les paiements courants vers l'étranger selon le Règlement RFE UEMOA ?","choices":["L'achat de biens immobiliers à l'étranger","Les paiements résultant de la livraison de marchandises, frais portuaires, salaires, impôts, intérêts, dividendes, loyers, transferts d'émigrants, etc.","Les investissements directs sans autorisation","Les acquisitions de titres étrangers sans déclaration"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 9 et Art. 2 (point 52, opérations courantes)"},{"cat":"Opérations courantes","q":"Les résidents sont-ils tenus de domicilier les opérations d'importation et d'exportation auprès d'un intermédiaire agréé ?","choices":["Non, c'est facultatif","Oui, dans les conditions de l'Annexe II du Règlement","Uniquement les exportations supérieures à 10 millions FCFA","Uniquement si l'opération dépasse 5 millions FCFA"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 10 (opérations courantes soumises à domiciliation)"},{"cat":"Opérations courantes","q":"Les paiements à destination de l'étranger pour règlements d'assurances, primes et indemnités font-ils partie des opérations autorisées à titre général ?","choices":["Non, ils nécessitent toujours une autorisation préalable","Oui, ils figurent dans la liste des paiements courants autorisés à titre général","Uniquement si l'assureur est étranger","Uniquement pour les contrats supérieurs à 1 million FCFA"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 9 et Art. 2 (point 52, opérations courantes)"},{"cat":"Opérations en capital","q":"Quel est le régime des mouvements de capitaux entre États membres de l'UEMOA ?","choices":["Soumis à autorisation préalable du Ministre des Finances","Libres et sans restriction aucune, conformément aux Articles 76d, 96 et 97 du Traité UEMOA modifié","Soumis à déclaration préalable à la BCEAO","Limités à 50 millions FCFA par opération"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 3 (Liberté des mouvements de capitaux au sein de l'UEMOA)"},{"cat":"Opérations en capital","q":"Tout investissement à l'étranger effectué par un résident UEMOA est-il soumis à une procédure particulière ?","choices":["Non, libre","Oui, autorisation préalable du Ministre chargé des Finances + financement à 75% au moins par emprunts à l'étranger","Simple déclaration à la BCEAO","Autorisation de la Commission Bancaire"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 12 (Investissement à l'étranger par les résidents)"},{"cat":"Opérations en capital","q":"Quel pourcentage minimum d'un investissement à l'étranger doit être financé par des emprunts à l'étranger pour un résident UEMOA ?","choices":["25%","50%","75%","100%"],"answer":2,"source":"Règlement n°06/2024/CM/UEMOA — Art. 12 (financement à 75% au moins par emprunt à l'étranger)"},{"cat":"Opérations en capital","q":"La constitution d'investissements étrangers dans un État UEMOA est-elle soumise à autorisation ?","choices":["Oui, autorisation préalable du Ministre des Finances","Non, libre — mais soumise à déclaration à la Direction chargée des Finances Extérieures et à la BCEAO à des fins statistiques (pour investissements directs)","Soumise à autorisation BCEAO","Soumise à autorisation Commission UEMOA"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 15 (investissements directs étrangers/portefeuille libres + déclaration statistique)"},{"cat":"Opérations en capital","q":"Le réinvestissement à l'étranger du produit de la liquidation d'un investissement d'un résident est-il libre ?","choices":["Oui, libre","Non — il est soumis à autorisation préalable du Ministre chargé des Finances ; à défaut, le produit doit être rapatrié dans le délai fixé par la BCEAO","Soumis à autorisation BCEAO","Soumis à autorisation du CREPMF"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 12 (réinvestissement soumis à autorisation préalable, à défaut rapatriement)"},{"cat":"Opérations en capital","q":"Les emprunts contractés par des résidents auprès de non-résidents sont soumis à quelle obligation principale ?","choices":["Autorisation préalable systématique","Réalisation par l'entremise d'intermédiaires agréés + déclaration statistique obligatoire à la Direction des Finances Extérieures et à la BCEAO","Plafond de 100 millions FCFA","Aucune obligation"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 16 (emprunts à l'étranger : libres + déclaration statistique)"},{"cat":"Opérations en capital","q":"Les transactions sur instruments dérivés de change effectuées par des résidents doivent-elles être adossées à des opérations sous-jacentes ?","choices":["Non, elles sont libres","Oui, elles doivent être adossées à des opérations commerciales ou financières","Uniquement pour les montants supérieurs à 1 milliard FCFA","Adossement obligatoire uniquement pour les contrats > 6 mois"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 18 (Instruments dérivés de change)"},{"cat":"Or & valeurs mobilières","q":"L'importation et l'exportation d'or entre l'UEMOA et l'étranger sont-elles libres ?","choices":["Oui, libres","Non — soumises à autorisation préalable du Ministre chargé des Finances","Soumises à autorisation BCEAO uniquement","Soumises à déclaration au CREPMF"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 20 (Importation et exportation d'or)"},{"cat":"Or & valeurs mobilières","q":"Quel est le poids maximum d'objets en or qu'un voyageur peut importer ou exporter sans autorisation préalable ?","choices":["100 grammes","250 grammes","500 grammes","1 kilogramme"],"answer":2,"source":"Règlement n°06/2024/CM/UEMOA — Art. 20 (dispenses : voyageurs, limite 500 g)"},{"cat":"Or & valeurs mobilières","q":"Qui peut effectuer des importations ou exportations d'or SANS autorisation préalable ?","choices":["Tout commerçant agréé","Le Trésor public et la BCEAO, ainsi que pour des objets contenant une faible quantité d'or, et les voyageurs dans la limite de 500 g","Toute banque","Toute société minière"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 20 (dispenses de l'autorisation préalable)"},{"cat":"Or & valeurs mobilières","q":"Quelle autorité doit autoriser l'émission, l'exposition et la mise en vente dans l'UEMOA de titres d'États étrangers, collectivités publiques ou sociétés étrangères ?","choices":["Le Ministre chargé des Finances","La BCEAO, dont l'autorisation préalable est requise avant le visa de l'AMF-UMOA en matière d'appel public à l'épargne","L'AMF-UMOA directement","La Commission Bancaire UMOA"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 17 (autorisation préalable BCEAO avant visa de l'AMF-UMOA)"},{"cat":"Or & valeurs mobilières","q":"Le démarchage auprès de résidents UEMOA en vue de la constitution de dépôts de fonds à l'étranger est-il libre ?","choices":["Oui, libre","Non — soumis à autorisation BCEAO pour le compte de l'Autorité RFE","Soumis à déclaration au CREPMF","Interdit dans tous les cas"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 17 (point 2, démarchage à l'étranger)"},{"cat":"Sanctions & responsabilités","q":"Qui veille au respect des prescriptions du Règlement RFE pour les opérations effectuées par leur entremise ?","choices":["La Commission UEMOA uniquement","Les intermédiaires habilités (intermédiaires agréés + agréés de change manuel)","Les services douaniers","Le Conseil régional CREPMF"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 25 (Responsabilités des intermédiaires habilités)"},{"cat":"Sanctions & responsabilités","q":"Quelle sanction additionnelle peut frapper un intermédiaire agréé ou un agréé de change manuel ayant commis une infraction au Règlement RFE ?","choices":["Une amende fixe de 10 millions FCFA","Le retrait de son agrément, en plus des autres sanctions prévues","Une suspension temporaire de 3 mois","Une mise en demeure publique"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 28 (Sanctions — retrait d'agrément)"},{"cat":"Sanctions & responsabilités","q":"Quelles autorités sanctionnent les infractions au Règlement RFE commises par les établissements de crédit ?","choices":["Le Ministre des Finances uniquement","La BCEAO et la Commission Bancaire de l'UMOA, au regard des dispositions de la loi bancaire en vigueur dans chaque État membre","Les tribunaux civils nationaux","Le CREPMF"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 28 (BCEAO et Commission Bancaire de l'UMOA)"},{"cat":"Sanctions & responsabilités","q":"Les intermédiaires habilités doivent-ils rendre compte des paiements émis ou reçus de l'étranger ?","choices":["Non, secret bancaire","Oui — ils doivent rendre compte à la Direction chargée des Finances Extérieures et à la BCEAO à des fins de contrôle","Uniquement pour les opérations supérieures à 100 millions FCFA","Uniquement annuellement"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 24 (Comptes rendus au Ministère des Finances et à la BCEAO)"},{"cat":"Sanctions & responsabilités","q":"Le Règlement RFE UEMOA s'applique-t-il sans préjudice de la législation LBC/FT (Lutte contre le Blanchiment de Capitaux et le Financement du Terrorisme) ?","choices":["Non, il prime sur la législation LBC/FT","Oui — sa mise en œuvre s'applique sans préjudice du respect de la législation LBC/FT en vigueur dans les États membres","Il remplace la législation LBC/FT","Les deux régimes sont indépendants et non liés"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Art. 30 (Respect de la législation LBC/FT/FPADM)"},{"cat":"Postes & administration","q":"L'Administration ou l'Office des Postes peut exécuter des ordres de transfert vers l'étranger pour le règlement d'importations de marchandises dans la limite de quel montant ?","choices":["100.000 FCFA","500.000 FCFA","1.000.000 FCFA","5.000.000 FCFA"],"answer":2,"source":"Règlement n°06/2024/CM/UEMOA — Annexe I, Art. 5 (plafond fixé par la BCEAO)"},{"cat":"Postes & administration","q":"L'Administration ou l'Office des Postes est-il obligé de rétrocéder les recettes perçues en devises en provenance de l'étranger ?","choices":["Non, il peut les conserver","Oui, à la BCEAO contre crédit en compte","Au Ministre des Finances","Au Trésor public national"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Annexe I, Art. 6 (rétrocession des devises à la BCEAO)"},{"cat":"Postes & administration","q":"Pour les transferts hors UEMOA effectués par l'Office des Postes, quel est le montant en dessous duquel aucune pièce justificative n'est exigée ?","choices":["100.000 FCFA","300.000 FCFA","500.000 FCFA","1.000.000 FCFA"],"answer":2,"source":"Règlement n°06/2024/CM/UEMOA — Annexe I, Art. 5 (plafond fixé par la BCEAO)"},{"cat":"BCEAO & rôle","q":"Quel pouvoir spécifique le Ministre chargé des Finances peut-il déléguer à la BCEAO en matière RFE ?","choices":["Le pouvoir de sanctionner les infractions","Le pouvoir d'autoriser les transferts sur l'étranger ou d'instruire les dossiers de demandes d'autorisations préalables, avec compte rendu mensuel obligatoire","Le pouvoir de fixer les plafonds de transfert","Le pouvoir de retirer les agréments"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Annexe I, Art. 3 (délégation de pouvoir à la BCEAO)"},{"cat":"BCEAO & rôle","q":"Quel type d'actes la BCEAO peut-elle publier sous son timbre pour préciser l'application des textes RFE ?","choices":["Uniquement des règlements","Des Instructions, Décisions, Avis, Notes et Lettres aux intermédiaires agréés","Uniquement des décisions du Conseil d'Administration","Uniquement des circulaires conjointes avec la Commission UEMOA"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Annexe I, Art. 2 (Instructions, Décisions, Avis, Notes et Lettres)"},{"cat":"BCEAO & rôle","q":"Dans le cadre de sa mission de contrôle RFE, la BCEAO peut-elle demander des justificatifs aux intermédiaires agréés ?","choices":["Non, seulement le Ministre des Finances","Oui — elle peut demander les justificatifs de toutes les opérations de change qu'ils exécutent","Uniquement après accord judiciaire","Uniquement sur dénonciation"],"answer":1,"source":"Règlement n°06/2024/CM/UEMOA — Annexe I, Art. 4 (Contrôle BCEAO)"},{"cat":"Ressortissants étrangers résidents","q":"Selon la Note BCEAO n°013-04-2026, à partir de quelle condition un salarié étranger résidant dans l'UEMOA est-il considéré comme résident ?","choices":["Présence physique continue de 6 mois","Contrat de travail à durée indéterminée OU d'une durée supérieure ou égale à un an","Inscription au registre du commerce local","Mariage avec un ressortissant UEMOA"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 1 (Appréciation de la qualité de résident, 17 avril 2026)"},{"cat":"Ressortissants étrangers résidents","q":"Les ressortissants étrangers ayant acquis le statut de résident de l'Union sont-ils autorisés à détenir des comptes ordinaires en francs CFA ?","choices":["Non, uniquement des comptes étrangers","Oui — un ou plusieurs comptes ordinaires libellés en FCFA auprès d'un ou plusieurs intermédiaires agréés de leur choix","Uniquement un seul compte chez la BCEAO","Uniquement après autorisation du Ministre des Finances"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 2 (Principes généraux applicables aux ressortissants étrangers devenus résidents)"},{"cat":"Ressortissants étrangers résidents","q":"Tout paiement entre un ressortissant étranger devenu résident et un autre résident de l'Union (notamment règlement des revenus du travail) doit être libellé en quelle monnaie ?","choices":["Au choix des parties","Exclusivement en francs CFA et versé sur un compte tenu auprès d'un intermédiaire agréé de l'Union","En euros, dollars ou FCFA","Dans la monnaie du pays d'origine du salarié"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 2 (Règlement des revenus du travail)"},{"cat":"Ressortissants étrangers résidents","q":"Les comptes bancaires ouverts à l'étranger par les ressortissants étrangers AVANT l'acquisition du statut de résident peuvent-ils être maintenus ?","choices":["Non, ils doivent être clôturés dans les 3 mois","Oui — ils peuvent être maintenus après l'acquisition de la qualité de résident, sans autorisation préalable du Ministre chargé des Finances","Uniquement avec autorisation BCEAO","Uniquement si le solde est inférieur à 1 million FCFA"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 2 (Maintien des comptes à l'étranger)"},{"cat":"Ressortissants étrangers résidents","q":"Selon la Note BCEAO n°013-04-2026, quelle est la liste des dépenses courantes autorisées à titre général pour les transferts à l'étranger des ressortissants étrangers résidents ?","choices":["Uniquement les frais de scolarité","Acquisition de biens et services, paiement de loyers, règlement d'impôts et taxes, aides familiales, frais de scolarité, autres transferts courants sans contrepartie","Uniquement les transferts familiaux","Uniquement les pensions"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 3 (Opérations de paiements extérieurs — Dépenses courantes)"},{"cat":"Ressortissants étrangers résidents","q":"Pour l'approvisionnement de comptes bancaires à l'étranger à des fins de constitution d'épargne sur revenus salariaux, quelle est la durée MINIMALE de constitution de l'épargne ?","choices":["3 mois","6 mois","12 mois","24 mois"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 3 (Approvisionnement de comptes à l'étranger : 6 mois minimum)"},{"cat":"Ressortissants étrangers résidents","q":"Dans quel délai maximum la Structure chargée des Finances Extérieures doit-elle délivrer l'autorisation pour un transfert d'épargne d'un résident étranger ?","choices":["2 jours ouvrés","5 jours ouvrés","15 jours ouvrés","30 jours calendaires"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 3 (Délai max : 5 jours ouvrés)"},{"cat":"Ressortissants étrangers résidents","q":"Un ressortissant étranger ayant acquis la qualité de résident et quittant définitivement l'UEMOA peut-il transférer le solde de ses comptes en FCFA à l'étranger ?","choices":["Non, le solde est bloqué","Oui — sans limitation de montant, après autorisation préalable de la Structure chargée des Finances Extérieures, sous réserve que les avoirs soient dûment justifiés et proviennent de revenus perçus dans l'Union ou de la liquidation d'investissements","Uniquement dans la limite de 50 millions FCFA","Uniquement si le départ est lié à la fin d'un contrat de travail"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 4 (Transfert du solde en cas de départ définitif)"},{"cat":"Ressortissants étrangers résidents","q":"Quelle est l'une des trois pièces principales exigées pour qu'un ressortissant étranger résident soit éligible aux transferts de revenus prévus par la Note BCEAO 013-04-2026 ?","choices":["Un acte de naissance traduit","Un bulletin de salaire, ou une attestation de pension de retraite, ou un document fiscal attestant de la réception de revenus","Un casier judiciaire vierge","Un permis de séjour de plus de 5 ans"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 5 (Critères d'éligibilité — justification de revenus professionnels)"},{"cat":"Ressortissants étrangers résidents","q":"Le montant cumulé des transferts autorisés à titre général par un ressortissant étranger résident peut-il dépasser ses revenus perçus dans l'Union ?","choices":["Oui, jusqu'à 200% des revenus","Non — il ne peut excéder celui des revenus nets perçus, dûment justifiés par des documents probants (bulletins de salaire, attestations, etc.)","Oui sans limite avec autorisation","Oui jusqu'à 150%"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 7 (Origine des revenus et plafond des transferts)"},{"cat":"Ressortissants étrangers résidents","q":"Qui est responsable de la conformité des opérations de transfert effectuées au titre de la Note BCEAO 013-04-2026 ?","choices":["Uniquement le client","Les intermédiaires agréés sont responsables de l'exécution, et les clients restent responsables de l'exactitude des informations, de l'authenticité des documents et de la licéité de l'origine des fonds","Uniquement la BCEAO","La Commission Bancaire"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 8 (Responsabilité des intervenants)"},{"cat":"Ressortissants étrangers résidents","q":"Les opérations réalisées en application de la Note BCEAO n°013-04-2026 sont-elles soumises aux obligations LBC/FT/FPADM ?","choices":["Non, elles en sont exemptées","Oui — elles demeurent soumises aux obligations de vigilance, de contrôle interne et de déclaration en matière de lutte contre le blanchiment, le financement du terrorisme et la prolifération des armes de destruction massive","Uniquement au-dessus de 10 millions FCFA","Uniquement pour les transferts hors Zone franc"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 9 (Obligations LBC/FT/FPADM)"},{"cat":"Ressortissants étrangers résidents","q":"Sur quel fondement juridique la Note BCEAO n°013-04-2026 a-t-elle été prise ?","choices":["Sur le Règlement n°09/2010/CM/UEMOA","Sur l'article 31 du Règlement n°06/2024/CM/UEMOA du 20 décembre 2024 et l'article 2 de l'Annexe I dudit Règlement","Sur une décision du Conseil des Ministres UEMOA de mars 2026","Sur une circulaire BCEAO interne"],"answer":1,"source":"Note BCEAO n°013-04-2026 — Préambule (Fondement juridique)"},{"cat":"Ressortissants étrangers résidents","q":"Les transferts d'épargne sur revenus salariaux ou pension de retraite peuvent-ils porter sur la totalité ou seulement une partie de l'épargne constituée ?","choices":["Uniquement la totalité","Uniquement la moitié","La demande peut porter sur tout ou partie de l'épargne constituée","Maximum 30% de l'épargne"],"answer":2,"source":"Note BCEAO n°013-04-2026 — § 3 (Modalités du transfert d'épargne)"},{"cat":"Ressortissants étrangers résidents","q":"Quel délai minimum doit s'écouler entre deux demandes de transferts d'épargne fondées sur le même motif ?","choices":["1 mois","3 mois","6 mois","12 mois"],"answer":2,"source":"Note BCEAO n°013-04-2026 — § 3 (Délai minimum entre deux demandes : 6 mois identique à la période minimale)"},{"cat":"Ressortissants étrangers résidents","q":"Quels documents le client doit-il fournir pour le remboursement d'un emprunt contracté à l'étranger en application de la Note BCEAO 013-04-2026 ?","choices":["Aucun, simple déclaration","La convention d'emprunt, l'échéancier d'amortissement et une attestation d'engagements délivrée par le prêteur non-résident","Uniquement le contrat de prêt","Uniquement l'avis de virement bancaire"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 3 (Modalités spécifiques aux remboursements d'emprunts)"},{"cat":"Ressortissants étrangers résidents","q":"Pour les transferts ayant un objet récurrent (loyers, factures, etc.) d'un ressortissant étranger résident, peut-on constituer un dossier unique ?","choices":["Non, chaque transfert doit faire l'objet d'un dossier séparé","Oui — un dossier unique peut être constitué auprès d'un intermédiaire agréé, renouvelé annuellement, et sert de base justificative pour 12 mois","Uniquement pour les transferts mensuels fixes","Uniquement pour les contrats supérieurs à 1 an"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 3 (Dossier unique pour transferts récurrents, renouvellement annuel)"},{"cat":"Ressortissants étrangers résidents","q":"Quels justificatifs de lien avec le pays de destination doit fournir un ressortissant étranger résident pour bénéficier des modalités de transfert prévues par la Note BCEAO 013-04-2026 ?","choices":["Aucun lien requis","Une obligation fiscale, OU une attache familiale, OU une obligation financière ou contractuelle dûment établie dans le pays de destination","Un acte de propriété dans le pays de destination","Une promesse d'embauche dans le pays de destination"],"answer":1,"source":"Note BCEAO n°013-04-2026 — § 5 (Critères d'éligibilité — lien avec pays de destination)"}];
const QB = [{"cat":"Fonds propres","q":"Quel est le ratio minimum de fonds propres de base de catégorie 1 (CET1) exigé des établissements de crédit de l'UMOA ?","choices":["4,5% des risques pondérés","5% des risques pondérés","6% des risques pondérés","8% des risques pondérés"],"answer":1,"source":"Avis n°004-04-2016 BCEAO — Art. 24 (Titre III)"},{"cat":"Fonds propres","q":"Quel est le ratio minimum de fonds propres de catégorie 1 (Tier 1 = CET1 + AT1) ?","choices":["5%","6%","7,5%","8%"],"answer":1,"source":"Décision 013/2016 CM/UMOA — Annexe Titre III §103"},{"cat":"Fonds propres","q":"Quel est le ratio minimum de fonds propres effectifs (FPE = T1 + T2) hors coussins ?","choices":["7%","8%","10,5%","12%"],"answer":1,"source":"Décision 013/2016 CM/UMOA — Annexe §103"},{"cat":"Fonds propres","q":"Quel est le niveau du coussin de conservation des fonds propres en cible 2022 ?","choices":["1,25%","1,875%","2,5%","3%"],"answer":2,"source":"Décision 013/2016 CM/UMOA — Annexe Titre III (Coussin de conservation)"},{"cat":"Fonds propres","q":"Le coussin contracyclique imposable par la BCEAO peut atteindre quel niveau maximum ?","choices":["1%","1,5%","2,5%","5%"],"answer":2,"source":"Décision 013/2016 CM/UMOA — Annexe (Coussin contracyclique)"},{"cat":"Fonds propres","q":"Quel est le total des exigences minimales en fonds propres (FPE + coussin de conservation) à horizon 2022 ?","choices":["8%","9,5%","10,5%","12,5%"],"answer":2,"source":"Décision 013/2016 CM/UMOA — Annexe Titre III (cible pleine 2022)"},{"cat":"Fonds propres","q":"Quelles sont les trois grandes composantes des fonds propres effectifs (FPE) au sens du dispositif prudentiel UMOA ?","choices":["Capital + Réserves + Provisions","CET1 + AT1 + T2","Tier 1 + Tier 2 + Tier 3","Fonds propres durs + Quasi-fonds propres + Dettes subordonnées"],"answer":1,"source":"Annexe Décision 013/2016 — §12 (Composantes des fonds propres)"},{"cat":"Fonds propres","q":"Que représentent les fonds propres de base durs (CET1) dans la structure des fonds propres ?","choices":["Les fonds propres de qualité moyenne","Les fonds propres de meilleure qualité permettant la continuité d'exploitation","Les fonds propres absorbant les pertes uniquement en liquidation","Les fonds propres remboursables à court terme"],"answer":1,"source":"Annexe Décision 013/2016 — §11(a) (Définition CET1)"},{"cat":"Fonds propres","q":"Quels éléments composent principalement le CET1 ?","choices":["Dettes subordonnées et obligations convertibles","Capital social libéré (actions ordinaires), primes d'émission, report à nouveau créditeur, réserve spéciale, réserves statutaires","Provisions générales et plus-values latentes","Comptes courants d'associés et avances en compte"],"answer":1,"source":"Annexe Décision 013/2016 — §15 (Éléments composant le CET1)"},{"cat":"Fonds propres","q":"Quel pourcentage des bénéfices nets annuels doit être affecté à la réserve spéciale obligatoire des banques UMOA ?","choices":["5%","10%","15%","20%"],"answer":2,"source":"Annexe Décision 013/2016 — §16 (Réserve spéciale, prélèvement 15%)"},{"cat":"Fonds propres","q":"À partir de quel niveau de réserve spéciale la dotation cesse-t-elle d'être obligatoire ?","choices":["Lorsqu'elle atteint le dixième du capital social","Lorsqu'elle atteint le cinquième (20%) du montant du capital social, ET que les ratios cibles sont respectés","Lorsqu'elle atteint la moitié du capital social","Elle ne cesse jamais d'être obligatoire"],"answer":1,"source":"Annexe Décision 013/2016 — §16 (Conditions de cessation de dotation)"},{"cat":"Fonds propres","q":"Pour intégrer le bénéfice intermédiaire dans le CET1, quelle condition principale est requise ?","choices":["Décision de l'AG uniquement","Vérification par les commissaires aux comptes + déduction des charges et dividendes prévisibles","Approbation du Conseil d'Administration uniquement","Aucune vérification spécifique"],"answer":1,"source":"Annexe Décision 013/2016 — §18 (Conditions intégration du bénéfice)"},{"cat":"Fonds propres","q":"Que sont les fonds propres de base additionnels (AT1) ?","choices":["Des fonds propres complémentaires de qualité supérieure au CET1","Une composante des fonds propres de base de qualité moindre que le CET1, mais stable pour absorber les pertes et permettre la continuité d'exploitation","Des dettes subordonnées sans capacité d'absorption","Des provisions générales pour risques bancaires"],"answer":1,"source":"Annexe Décision 013/2016 — §11(b) (Définition AT1)"},{"cat":"Fonds propres","q":"Que représentent les fonds propres complémentaires (T2) ?","choices":["Des fonds propres équivalents au CET1","Des fonds propres de qualité moindre que les AT1 mais avec capacité d'absorption de pertes en cas de LIQUIDATION","Des dettes seniors classiques","Le report à nouveau créditeur uniquement"],"answer":1,"source":"Annexe Décision 013/2016 — §11(c) (Définition T2)"},{"cat":"Fonds propres","q":"Pour les instruments AT1 et T2, quelle clause contractuelle est obligatoire ?","choices":["Aucune clause particulière","Clause de conversion intégrale et permanente en actions ordinaires OU annulation en cas de point de non-viabilité","Clause de remboursement anticipé garanti","Clause de paiement de dividendes prioritaires"],"answer":1,"source":"Annexe Décision 013/2016 — §13 (Clause de conversion au point de non-viabilité)"},{"cat":"Fonds propres","q":"Que désignent les « participations significatives » dans une autre entité financière ?","choices":["Détention < 5% des actions ordinaires","Détention < 10% des actions ordinaires","Détention > 10% des actions ordinaires","Détention > 50% des actions ordinaires"],"answer":2,"source":"Annexe Décision 013/2016 — §14(g) (Participations significatives)"},{"cat":"Fonds propres","q":"Quel est le seuil de détention qui distingue les participations non significatives des significatives ?","choices":["5%","10%","20%","33%"],"answer":1,"source":"Annexe Décision 013/2016 — §14(f) et (g)"},{"cat":"Fonds propres","q":"Les participations croisées dans le capital d'autres EC/assurance ou entités financières sont :","choices":["Autorisées sans restriction","Visées comme problématiques car elles gonflent artificiellement les fonds propres","Encouragées pour renforcer le système","Soumises uniquement à déclaration"],"answer":1,"source":"Annexe Décision 013/2016 — §14(e) (Participations croisées)"},{"cat":"Liquidité","q":"Le Ratio de Liquidité à Court Terme (RLCT / LCR) impose aux banques de couvrir leurs sorties nettes de trésorerie sur quel horizon ?","choices":["7 jours","15 jours","30 jours","90 jours"],"answer":2,"source":"Instruction n°009-09-2017 BCEAO — Art. 4 (LCR stress 30 jours)"},{"cat":"Liquidité","q":"Quel niveau minimum doit atteindre le RLCT à pleine application ?","choices":["75%","100%","110%","125%"],"answer":1,"source":"Instruction n°009-09-2017 BCEAO — Art. 5 (RLCT ≥ 100%)"},{"cat":"Liquidité","q":"Le Ratio de Liquidité à Long Terme (RLLT / NSFR) compare quels éléments ?","choices":["Actifs liquides / dépôts à vue","Financement stable disponible / financement stable exigé","Crédits à terme / dépôts à terme","Fonds propres / engagements hors bilan"],"answer":1,"source":"Instruction n°009-09-2017 BCEAO — Art. 7 (NSFR : ASF/RSF ≥ 100%)"},{"cat":"Liquidité","q":"Quel est le ratio minimum exigé pour le NSFR (RLLT) à pleine application ?","choices":["75%","90%","100%","120%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre XIII (NSFR ≥ 100%)"},{"cat":"Liquidité","q":"Le LCR vise à garantir qu'un établissement dispose d'actifs liquides de haute qualité (HQLA) suffisants pour faire face à :","choices":["Une crise prolongée de 12 mois","Une période de stress de liquidité de 30 jours calendaires","Les retraits quotidiens normaux","Les besoins de financement structurel"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XIII (LCR, stress 30 jours)"},{"cat":"Liquidité","q":"Le NSFR a pour objectif principal :","choices":["Couvrir le risque de marché à court terme","Promouvoir la résilience à moyen et long terme en exigeant un financement plus stable des actifs et activités hors bilan","Réduire les exigences de fonds propres","Augmenter la liquidité immédiate"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XIII (Objectif NSFR)"},{"cat":"Liquidité","q":"Les actifs liquides de haute qualité (HQLA) utilisés dans le calcul du LCR doivent être :","choices":["Uniquement des espèces","Facilement et immédiatement convertibles en espèces, avec peu ou pas de perte de valeur","Des actifs à long terme","Des actifs hypothécaires"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XIII (Caractéristiques des HQLA)"},{"cat":"Liquidité","q":"Le LCR doit-il être respecté à tout moment ?","choices":["Non, uniquement en fin de trimestre","Non, uniquement annuellement","Oui, en permanence, et déclaré mensuellement","Uniquement en cas de crise"],"answer":2,"source":"Instruction n°009-09-2017 BCEAO — Art. 5"},{"cat":"Liquidité","q":"Pour les fonds propres requis dans le numérateur du LCR, on retient :","choices":["Les fonds propres effectifs","Les actifs liquides de haute qualité (HQLA)","Les dépôts de la clientèle","Les encours interbancaires"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XIII (Numérateur LCR = HQLA)"},{"cat":"Liquidité","q":"Au dénominateur du LCR, on calcule :","choices":["Les fonds propres","Les sorties nettes de trésorerie attendues sur 30 jours en scénario de stress","Le total bilan","Les actifs pondérés"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XIII"},{"cat":"Liquidité","q":"Quelles entités sont assujetties au respect du LCR dans l'UMOA ?","choices":["Uniquement les banques systémiques","Toutes les banques et établissements financiers à caractère bancaire","Uniquement les filiales étrangères","Uniquement les EC dont le total bilan dépasse 100 Mds FCFA"],"answer":1,"source":"Instruction n°009-09-2017 BCEAO"},{"cat":"Division risques","q":"Quelle est la limite maximale d'exposition sur un même bénéficiaire (ou groupe de contreparties liées) en % des fonds propres effectifs ?","choices":["10%","20%","25%","40%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre VII Art. 56 (25% des FPE)"},{"cat":"Division risques","q":"À partir de quel seuil une exposition est-elle considérée comme un « grand risque » devant être déclaré à la Commission Bancaire ?","choices":["5% des FPE","10% des FPE","15% des FPE","20% des FPE"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VII (Seuil de déclaration 10%)"},{"cat":"Division risques","q":"Quelle est la limite globale cumulée des grands risques en % des fonds propres effectifs ?","choices":["400%","600%","800%","1000%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre VII (Limite globale 8 fois les FPE)"},{"cat":"Division risques","q":"Pour le calcul des grands risques, les expositions à un même bénéficiaire incluent :","choices":["Uniquement les crédits directs","L'ensemble des engagements (crédits, garanties, dérivés, hors bilan) sur le bénéficiaire et les contreparties qui lui sont liées","Uniquement les engagements bilanciels","Uniquement les expositions à plus d'1 an"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VII (Calcul des grands risques)"},{"cat":"Division risques","q":"Qu'entend-on par « groupe de contreparties liées » dans le dispositif de division des risques ?","choices":["Toutes les contreparties d'un même secteur d'activité","Deux ou plusieurs personnes physiques ou morales qui constituent un risque unique en raison de liens de contrôle ou d'interdépendance économique","Toutes les contreparties d'un même pays","Les contreparties bénéficiant du même taux d'intérêt"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VII (Définition groupe de contreparties liées)"},{"cat":"Division risques","q":"Les expositions sur les États souverains de l'UEMOA en monnaie locale sont-elles soumises aux limites de la division des risques ?","choices":["Oui, plafonnées à 25%","Non, elles bénéficient d'une exemption en raison de leur pondération nulle","Oui, plafonnées à 50%","Oui, plafonnées à 100%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VII (Exemptions)"},{"cat":"Division risques","q":"Les expositions sur la BCEAO sont :","choices":["Soumises à la limite de 25%","Exemptées des limites de division des risques","Soumises à une limite spéciale de 100%","Pondérées à 100%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VII (Exemptions BCEAO)"},{"cat":"Gouvernance","q":"Quel organe est obligatoire au sein du conseil d'administration de tout établissement de crédit selon le dispositif UMOA ?","choices":["Comité de rémunération uniquement","Comité d'audit","Comité stratégie commerciale","Aucun comité n'est obligatoire"],"answer":1,"source":"Circulaire n°01-2017 CB-UMOA — Art. 24 (Comité d'audit obligatoire)"},{"cat":"Gouvernance","q":"Combien d'administrateurs indépendants sont exigés au minimum dans le conseil d'administration ?","choices":["Aucun","Au moins 1","Au moins 2","Au moins le tiers"],"answer":2,"source":"Circulaire n°01-2017 CB-UMOA — Art. 18 (Min. 2 administrateurs indépendants)"},{"cat":"Gouvernance","q":"La fonction de contrôle interne doit obligatoirement être indépendante de quelles autres fonctions ?","choices":["Audit interne uniquement","Conformité uniquement","Audit interne et gestion des risques","Direction générale uniquement"],"answer":2,"source":"Circulaire n°04-2017 CB-UMOA — Art. 8 (3 lignes de défense)"},{"cat":"Gouvernance","q":"Combien de lignes de défense compose le dispositif de contrôle interne d'un établissement de crédit UMOA ?","choices":["1 ligne","2 lignes","3 lignes","4 lignes"],"answer":2,"source":"Circulaire n°04-2017 CB-UMOA (3 lignes : opérationnel / risques+conformité / audit interne)"},{"cat":"Gouvernance","q":"Que se passe-t-il en cas de non-respect des normes prudentielles par un établissement de crédit ?","choices":["Aucune conséquence si régularisation sous 30 jours","La Commission Bancaire adresse une injonction + interdiction de distributions discrétionnaires (dividendes, rachats d'actions, primes) durant la période de non-conformité","Sanction pénale immédiate","Retrait automatique d'agrément"],"answer":1,"source":"Annexe Décision 013/2016 — §3 (Injonction + interdiction distributions)"},{"cat":"Gouvernance","q":"L'agrément des dirigeants d'un établissement de crédit relève de :","choices":["L'Assemblée Générale uniquement","La Commission Bancaire de l'UMOA","Le Ministre des Finances","Le Conseil d'Administration uniquement"],"answer":1,"source":"Loi uniforme portant réglementation bancaire"},{"cat":"Gouvernance","q":"Les exigences en matière de gouvernance s'appliquent-elles aux compagnies financières ?","choices":["Non, uniquement aux banques","Oui, sur base individuelle et consolidée","Uniquement aux filiales","Uniquement aux maisons-mères"],"answer":1,"source":"Décision 014/2016 CM/UMOA — Art. 7 (Application aux compagnies financières)"},{"cat":"Piliers Bâle","q":"Le Pilier 1 du dispositif prudentiel UMOA couvre principalement :","choices":["La gouvernance et la transparence","Les exigences minimales de fonds propres (risque de crédit, de marché, opérationnel)","Le processus de surveillance prudentielle","La discipline de marché"],"answer":1,"source":"Annexe Décision 013/2016 — Architecture Bâle II/III (Pilier 1)"},{"cat":"Piliers Bâle","q":"Le Pilier 2 (processus de surveillance prudentielle) inclut notamment :","choices":["Le calcul du ratio Cooke","L'ICAAP (évaluation interne de l'adéquation des fonds propres) et le SREP","La publication semestrielle des comptes","Le ratio de levier uniquement"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XI (Pilier 2, ICAAP/SREP)"},{"cat":"Piliers Bâle","q":"Le Pilier 3 (discipline de marché) impose la publication :","choices":["Du seul bilan annuel","D'informations sur la structure des fonds propres, l'exposition aux risques et la gestion des risques","Des seuls ratios prudentiels","Du rapport d'audit externe uniquement"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XII (Pilier 3)"},{"cat":"Piliers Bâle","q":"Quelle est la périodicité minimale obligatoire de publication des informations du Pilier 3 ?","choices":["Mensuelle","Trimestrielle","Semestrielle","Annuelle"],"answer":2,"source":"Annexe Décision 013/2016 — Titre XII (Périodicité semestrielle)"},{"cat":"Piliers Bâle","q":"L'ICAAP (Processus Interne d'Évaluation de l'Adéquation des Fonds Propres) a pour objectif de :","choices":["Calculer le ratio Cooke","Permettre à l'établissement d'évaluer en interne l'adéquation de ses fonds propres face à l'ensemble de ses risques","Réduire les exigences de fonds propres","Externaliser l'évaluation des risques"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XI (ICAAP)"},{"cat":"Piliers Bâle","q":"Le SREP (Supervisory Review and Evaluation Process) est conduit par :","choices":["L'établissement de crédit lui-même","La Commission Bancaire de l'UMOA","Les commissaires aux comptes","Le Conseil d'Administration"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XI (Processus SREP par CB-UMOA)"},{"cat":"Piliers Bâle","q":"Le dispositif UMOA s'inspire de quelle architecture internationale ?","choices":["Bâle I uniquement","Bâle II et Bâle III","Solvabilité II","MiFID II"],"answer":1,"source":"Annexe Décision 013/2016 — Préambule (Architecture Bâle II/III adaptée à l'UMOA)"},{"cat":"Piliers Bâle","q":"Pour le Pilier 1, l'approche UMOA est :","choices":["Modèles internes avancés obligatoires","Approche STANDARD (pas de modèles internes)","Au choix de l'établissement","Approche par modèle propriétaire"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (Approche standard)"},{"cat":"Ratio levier","q":"Quel est le niveau minimum du ratio de levier (Tier 1 / Exposition totale) imposé aux établissements de l'UMOA ?","choices":["1%","2%","3%","5%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre VIII (Ratio de levier ≥ 3%)"},{"cat":"Ratio levier","q":"Le dispositif prudentiel UMOA est entré en vigueur à quelle date, avec quelle période de transition ?","choices":["1er janvier 2017 — transition 3 ans","1er janvier 2018 — transition jusqu'en 2022","1er juillet 2018 — transition 2 ans","1er janvier 2020 — transition 5 ans"],"answer":1,"source":"Décision 013/2016 CM/UMOA — Art. 3 (Entrée en vigueur 01/01/2018)"},{"cat":"Ratio levier","q":"Au numérateur du ratio de levier, on retient :","choices":["Les fonds propres effectifs (FPE)","Les fonds propres de catégorie 1 (Tier 1 = CET1 + AT1)","Le CET1 uniquement","Le T2 uniquement"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VIII (Numérateur = T1)"},{"cat":"Ratio levier","q":"Au dénominateur du ratio de levier, on calcule :","choices":["Les actifs pondérés des risques","Une mesure non pondérée de l'exposition totale (bilan + hors bilan)","Les seuls actifs liquides","Les fonds propres complémentaires"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VIII"},{"cat":"Ratio levier","q":"Le ratio de levier vise principalement à :","choices":["Augmenter les fonds propres pondérés","Limiter l'effet de levier excessif et compléter le ratio fondé sur les risques (filet de sécurité non risqué)","Remplacer les autres ratios","Réduire le coût du capital"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VIII (Objectif backstop)"},{"cat":"Ratio levier","q":"La période de transition du dispositif prudentiel UMOA s'étend de :","choices":["2018 à 2020","2018 à 2022","2017 à 2022","2019 à 2025"],"answer":1,"source":"Décision 013/2016 CM/UMOA — Art. 3 (Application pleine 2022)"},{"cat":"Ratio levier","q":"Pour le coussin de conservation, la transition se fait par paliers de :","choices":["0,5% par an","0,625% par an de 2019 à 2022","1% par an","2,5% en une seule fois"],"answer":1,"source":"Annexe Décision 013/2016 — Titre III (Transition coussin)"},{"cat":"Ratio levier","q":"Que se passe-t-il si un établissement ne respecte pas le coussin de conservation ?","choices":["Rien de particulier","Restrictions sur les distributions discrétionnaires (dividendes, rachats d'actions, primes variables) proportionnelles au non-respect","Sanction pénale immédiate","Retrait d'agrément"],"answer":1,"source":"Annexe Décision 013/2016 — Titre III (Restrictions distributions)"},{"cat":"APR","q":"Quelle est la pondération en risque d'une créance sur un État souverain de l'UEMOA libellée et financée en FCFA ?","choices":["0%","20%","50%","100%"],"answer":0,"source":"Annexe Décision 013/2016 — Titre IV Art. 46 (Pondération 0%)"},{"cat":"APR","q":"Quelle pondération s'applique à une créance sur la BCEAO ?","choices":["0%","20%","50%","100%"],"answer":0,"source":"Annexe Décision 013/2016 — Titre IV (Pondération 0% BCEAO)"},{"cat":"APR","q":"Quelle pondération s'applique à une exposition sur une banque de notation entre A+ et A- ?","choices":["20%","50%","75%","100%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (Pondération expositions bancaires)"},{"cat":"APR","q":"Pour les expositions sur les entreprises non notées, quelle pondération s'applique par défaut ?","choices":["75%","100%","150%","200%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (Pondération entreprises non notées 100%)"},{"cat":"APR","q":"Quelle pondération s'applique au portefeuille de crédits sur la clientèle de détail (retail) ?","choices":["50%","75%","100%","150%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (Pondération retail 75%)"},{"cat":"APR","q":"Pour les expositions de financement immobilier résidentiel intégralement garanties par une hypothèque, quelle pondération s'applique ?","choices":["20%","35%","75%","100%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (Pondération hypothécaire résidentiel 35%)"},{"cat":"APR","q":"Les créances en souffrance (impayées de plus de 90 jours, non provisionnées ou avec provision < 20%) sont pondérées à :","choices":["75%","100%","150%","200%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre IV (Pondération créances en souffrance 150%)"},{"cat":"APR","q":"Les expositions sur les Banques Multilatérales de Développement (BMD) qualifiées (BIRD, BAD, etc.) sont pondérées à :","choices":["0%","20%","50%","100%"],"answer":0,"source":"Annexe Décision 013/2016 — Titre IV (BMD qualifiées : 0%)"},{"cat":"APR","q":"L'approche standard pour le risque de crédit dans l'UMOA s'appuie sur :","choices":["Des modèles internes des banques","Les notations externes (OEEC : Organismes Externes d'Évaluation du Crédit) reconnus par la Commission Bancaire","Les notations de la BCEAO uniquement","Aucune notation externe"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV Chapitre 1 (Approche standard)"},{"cat":"APR","q":"Que désigne l'« Atténuation du Risque de Crédit » (ARC) dans le dispositif prudentiel ?","choices":["L'annulation pure et simple du risque","L'ensemble des techniques (sûretés, garanties, dérivés de crédit) permettant de réduire l'exigence en fonds propres au titre du risque de crédit","Le rééchelonnement automatique des créances","Le partage du risque avec la BCEAO"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV Chapitre 3 (ARC)"},{"cat":"APR","q":"Quelle pondération s'applique à une exposition sur les PME éligibles au régime « retail » ?","choices":["50%","75%","100%","125%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (PME retail : 75%)"},{"cat":"APR","q":"Le « Facteur de Conversion en Équivalent Crédit » (FCEC) s'applique aux :","choices":["Expositions bilancielles uniquement","Engagements de hors bilan, pour les convertir en équivalent risque de crédit","Expositions sur les souverains","Dépôts à terme uniquement"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (FCEC pour hors bilan)"},{"cat":"APR","q":"Pour les engagements de crédit confirmés annulables sans condition, le FCEC est de :","choices":["0%","20%","50%","100%"],"answer":0,"source":"Annexe Décision 013/2016 — Titre IV (FCEC engagements annulables 0%)"},{"cat":"APR","q":"Pour les engagements de crédit confirmés d'une durée supérieure à 1 an, le FCEC est de :","choices":["0%","20%","50%","100%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre IV (FCEC engagements > 1 an : 50%)"},{"cat":"APR","q":"Quel est l'objectif principal du calcul des Actifs Pondérés des Risques (APR) ?","choices":["Déterminer le coût du capital","Mesurer l'exposition aux risques pour calculer les exigences minimales de fonds propres","Déterminer le résultat fiscal","Calculer la valeur ajoutée"],"answer":1,"source":"Annexe Décision 013/2016 — Titre III (Objectif APR)"},{"cat":"Risque opérationnel","q":"Que désigne le « risque opérationnel » dans le dispositif prudentiel UMOA ?","choices":["Uniquement les pertes liées à la fraude interne","Le risque de pertes résultant d'une inadéquation ou défaillance des processus internes, du personnel, des systèmes, ou d'événements externes","Le risque de marché","Le risque de crédit"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V (Définition risque opérationnel)"},{"cat":"Risque opérationnel","q":"Le risque opérationnel inclut-il le risque juridique ?","choices":["Non","Oui, le risque juridique est inclus dans le risque opérationnel","Uniquement pour les contentieux > 1 M FCFA","Uniquement les litiges avec la BCEAO"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V"},{"cat":"Risque opérationnel","q":"Le risque opérationnel exclut explicitement :","choices":["Le risque de fraude","Les risques stratégiques et de réputation","Le risque de défaillance des systèmes informatiques","Le risque d'erreur humaine"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V (Exclusions : stratégique et réputation)"},{"cat":"Risque opérationnel","q":"Quelle approche de calcul des exigences en fonds propres au titre du risque opérationnel est applicable dans l'UMOA ?","choices":["Approche AMA (Advanced Measurement Approach) uniquement","Approche standard fondée sur le Produit Net Bancaire (PNB) annuel sur 3 ans","Approche modèle interne uniquement","Aucune exigence spécifique"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V (Approche standard PNB)"},{"cat":"Risque opérationnel","q":"Le calcul des exigences en fonds propres au titre du risque opérationnel se base sur :","choices":["Le total bilan","Le PNB (Produit Net Bancaire) moyen des 3 derniers exercices, affecté d'un coefficient","Le résultat net","Les fonds propres"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V (Méthode de calcul)"},{"cat":"Risque opérationnel","q":"Si pour une année donnée le PNB est négatif ou nul, comment est-il pris en compte dans le calcul ?","choices":["Il est compté tel quel (négatif)","Il est exclu du calcul et le coefficient s'applique aux 2 années restantes","Il est forcé à zéro","Il est doublé"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V (PNB négatif/nul : exclusion)"},{"cat":"Risque opérationnel","q":"Le coefficient appliqué au PNB pour le calcul de l'exigence en fonds propres au titre du risque opérationnel est de :","choices":["8%","12%","15%","20%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre V (Coefficient 15%)"},{"cat":"Risque opérationnel","q":"La gestion du risque opérationnel doit inclure un dispositif de :","choices":["Modèle économique unique","Collecte des pertes opérationnelles, identification des indicateurs clés de risque (KRI), et plan de continuité d'activité (PCA)","Suppression de tous les processus manuels","Externalisation totale"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V (Cadre de gestion)"},{"cat":"Risque de marché","q":"Que regroupe le risque de marché dans le dispositif prudentiel ?","choices":["Uniquement le risque de change","Le risque de taux d'intérêt sur le portefeuille de négociation, le risque sur titres de propriété, le risque de change et le risque sur produits de base","Uniquement le risque de crédit","Le risque opérationnel"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI (Composantes du risque de marché)"},{"cat":"Risque de marché","q":"Le portefeuille de négociation se distingue du portefeuille bancaire par :","choices":["Sa taille uniquement","L'intention de négociation à court terme pour profiter des mouvements de prix, vs détention durable","La devise utilisée","Le secteur d'activité"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI Chapitre 1"},{"cat":"Risque de marché","q":"L'exigence en fonds propres au titre du risque de change s'applique :","choices":["Uniquement au portefeuille de négociation","À la position nette globale en devises de l'établissement (bilan + hors bilan)","Uniquement aux actifs libellés en EUR","Uniquement si la position dépasse 50% du capital"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI (Risque de change)"},{"cat":"Risque de marché","q":"Pour le risque de marché, l'UMOA applique :","choices":["L'approche par modèles internes","L'approche standard (méthode de mesure standardisée)","Au choix de l'établissement","Aucune exigence"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI Chapitre 2 (Approche standard)"},{"cat":"Risque de marché","q":"Le risque de taux d'intérêt dans le portefeuille bancaire (IRRBB) est-il traité au titre du Pilier 1 ?","choices":["Oui, exigence minimale standard","Non, il relève du Pilier 2 (processus de surveillance prudentielle)","Oui pour certaines banques uniquement","Il n'est pas couvert"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI / Pilier 2"},{"cat":"Risque de marché","q":"Pour les positions en titres de propriété (actions), le risque général de marché applique un coefficient de :","choices":["4%","8%","12%","16%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI Chapitre 2 (Actions : 8%)"},{"cat":"Risque de marché","q":"Pour les positions en produits de base (commodités), un coefficient additionnel s'applique au :","choices":["Notionnel","Risque spécifique et risque général","Bilan total","PNB"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI"},{"cat":"Risque de marché","q":"Une « petite » position nette en devises peut bénéficier d'une exemption d'exigence en fonds propres si elle est inférieure à :","choices":["1% du Tier 1","2% des FPE","5% du capital","10% du bilan"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI (Seuil minimum risque de change)"},{"cat":"Supervision consolidée","q":"Qui institue le dispositif de supervision sur base consolidée des EC et compagnies financières dans l'UMOA ?","choices":["L'Avis BCEAO 004-04-2016","La Décision N°014/24/06/2016/CM/UMOA du 24 juin 2016","La Loi uniforme bancaire","Le Traité UMOA"],"answer":1,"source":"Décision N°014/24/06/2016/CM/UMOA — Préambule"},{"cat":"Supervision consolidée","q":"Quel est le seuil de % du bilan groupe permettant de qualifier un groupe comme ayant des « activités à dominante bancaire » ?","choices":["20%","30%","40%","50%"],"answer":2,"source":"Décision 014/2016 — Art. 1(a) (Seuil 40%)"},{"cat":"Supervision consolidée","q":"Que désigne une « compagnie financière holding intermédiaire » ?","choices":["Toute société holding industrielle","Une entité non agréée comme EC, qui détient l'ensemble des participations d'un groupe dans ses filiales EC opérant dans l'UMOA","Une succursale étrangère","Une filiale d'assurance"],"answer":1,"source":"Décision 014/2016 — Art. 1(c)(ii)"},{"cat":"Supervision consolidée","q":"Que désigne le « contrôle exclusif de droit » ?","choices":["La détention de 25% des droits de vote","La détention directe ou indirecte de plus de la moitié des droits de vote d'une filiale","Un contrôle assuré par convention","Une influence sans détention"],"answer":1,"source":"Décision 014/2016 — Art. 1(e)(i)"},{"cat":"Supervision consolidée","q":"L'« influence notable » d'une entreprise sur une autre est présumée à partir de quel seuil de droits de vote ?","choices":["10%","20%","30%","50%"],"answer":1,"source":"Décision 014/2016 — Art. 1(m) (Présomption : >20%)"},{"cat":"Supervision consolidée","q":"Sont exclues du périmètre de consolidation prudentielle :","choices":["Toutes les entreprises à caractère financier","Les sociétés à objet commercial, entreprises non financières, et entreprises à caractère financier dont le bilan est < 1% du total consolidé","Uniquement les filiales étrangères","Aucune entité"],"answer":1,"source":"Décision 014/2016 — Art. 4 (Exclusions)"},{"cat":"Supervision consolidée","q":"Les entités du secteur des assurances sont-elles incluses dans le périmètre de consolidation prudentielle bancaire ?","choices":["Oui, sans distinction","Non, elles sont explicitement exclues","Uniquement si le bilan dépasse 10%","Uniquement pour les filiales contrôlées"],"answer":1,"source":"Décision 014/2016 — Art. 4 (Exclusion assurances)"},{"cat":"Supervision consolidée","q":"La Commission Bancaire peut requérir d'une maison-mère qu'elle crée dans l'UMOA :","choices":["Une filiale d'assurance","Une compagnie financière holding intermédiaire détenant les participations du groupe dans ses EC","Une fondation","Un comité scientifique"],"answer":1,"source":"Décision 014/2016 — Art. 5"},{"cat":"Supervision consolidée","q":"La supervision sur base consolidée s'applique aux :","choices":["EC maisons-mères détenant au moins une filiale EC dans l'UMOA, et compagnies financières holding ou holding intermédiaires implantées dans l'UMOA","Toutes les banques sans condition","Uniquement les groupes de plus de 5 banques","Uniquement les groupes étrangers"],"answer":0,"source":"Décision 014/2016 — Art. 3 (Champ d'application)"},{"cat":"Supervision consolidée","q":"La Commission Bancaire de l'UMOA tient et publie quelle liste annuelle ?","choices":["La liste des banques en faillite","La liste des compagnies financières qu'elle supervise sur base consolidée","La liste des actionnaires bancaires","La liste des prêts en souffrance"],"answer":1,"source":"Décision 014/2016 — Art. 6 (Liste annuelle)"},{"cat":"Supervision consolidée","q":"Quel est le pouvoir de la Commission Bancaire face à des structures de capital empêchant la supervision consolidée ?","choices":["Aucun pouvoir","Elle peut ne pas autoriser des structures de capital ou d'organisation qui font obstacle à la consolidation des données","Uniquement émettre des recommandations","Uniquement avec l'accord du Ministre"],"answer":1,"source":"Décision 014/2016 — Art. 9 (Pouvoirs)"},{"cat":"FODEP","q":"Que désigne le sigle FODEP dans la réglementation bancaire UMOA ?","choices":["Fonds de Développement Productif","Formulaire de Déclaration Prudentielle","Fonds d'Opérations Bancaires","Force Opérationnelle de Défense Prudentielle"],"answer":1,"source":"Instruction n°005-08-2017 BCEAO — Art. 3 (Définition FODEP)"},{"cat":"FODEP","q":"Quelle est la périodicité de transmission du FODEP à la BCEAO par les établissements assujettis ?","choices":["Mensuelle","Trimestrielle","Semestrielle","Annuelle"],"answer":2,"source":"Instruction n°005-08-2017 BCEAO — Art. 4 (Semestrielle)"},{"cat":"FODEP","q":"Quelles sont les dates limites de transmission du FODEP à la BCEAO ?","choices":["31 mars et 30 septembre","30 avril et 31 octobre","31 mai et 30 novembre","30 juin et 31 décembre"],"answer":1,"source":"Instruction n°005-08-2017 BCEAO — Art. 4 (30 avril et 31 octobre)"},{"cat":"FODEP","q":"Sur quelle base est arrêté le FODEP transmis au 30 avril ?","choices":["Les comptes du 1er trimestre","Les comptes annuels arrêtés au 31 décembre de l'année précédente","Les comptes au 30 juin","Les comptes prévisionnels"],"answer":1,"source":"Instruction n°005-08-2017 BCEAO — Art. 4"},{"cat":"FODEP","q":"Sur quelle base est arrêté le FODEP transmis au 31 octobre ?","choices":["Les comptes annuels","Les états financiers intermédiaires arrêtés au 30 juin de l'année en cours","Les comptes prévisionnels du 4ème trimestre","Les comptes au 30 septembre"],"answer":1,"source":"Instruction n°005-08-2017 BCEAO — Art. 4"},{"cat":"FODEP","q":"Le FODEP s'applique sur base :","choices":["Individuelle uniquement","Individuelle (banques et EFCB), sous-consolidée (compagnies financières holding intermédiaires) et consolidée (EC maisons-mères et compagnies financières holding)","Consolidée uniquement","Au choix"],"answer":1,"source":"Instruction n°005-08-2017 BCEAO — Art. 2 (Champ d'application)"},{"cat":"FODEP","q":"Par quel mode les EC transmettent-ils le FODEP à la BCEAO ?","choices":["Par courrier postal uniquement","Par l'intermédiaire de la plate-forme informatique dédiée à cet effet","Par fax","Par disquette informatique"],"answer":1,"source":"Instruction n°005-08-2017 BCEAO — Art. 5"},{"cat":"Définitions & gouvernance","q":"Le dispositif prudentiel UMOA s'applique sur quelles bases ?","choices":["Individuelle uniquement","Individuelle (banques et EFCB), sous-consolidée (compagnies financières holding intermédiaires), consolidée (EC maisons-mères et compagnies financières holding)","Consolidée uniquement","Au choix de l'établissement"],"answer":1,"source":"Annexe Décision 013/2016 — §2 (Champ d'application)"},{"cat":"Définitions & gouvernance","q":"Qu'entend-on par « établissement de crédit maison-mère » ?","choices":["Toute banque mère","Un EC qui n'est pas contrôlé par un autre EC ou compagnie financière, ET qui détient au moins une filiale qui est un autre EC","Une compagnie d'assurance","Une banque centrale"],"answer":1,"source":"Annexe Décision 013/2016 — §1(g) + Décision 014/2016 — Art. 1(i)"},{"cat":"Définitions & gouvernance","q":"La situation des succursales d'un établissement de crédit doit être :","choices":["Traitée séparément","Intégrée à celle de l'établissement qui en est propriétaire (pas de personnalité juridique distincte)","Soumise à un agrément séparé","Exclue du périmètre prudentiel"],"answer":1,"source":"Annexe Décision 013/2016 — §2 (Traitement des succursales)"},{"cat":"Définitions & gouvernance","q":"Quel est le rôle de la Commission Bancaire de l'UMOA dans le dispositif prudentiel ?","choices":["Émettre la monnaie","Autorité de supervision : injonctions de mise en conformité, sanctions, agrément des dirigeants, supervision consolidée","Fixer les taux directeurs","Gérer les réserves de change"],"answer":1,"source":"Annexe Décision 013/2016 + Décision 014/2016"}];
